Copilot generated this custom hook for me to handle form state. Does it look right?

```ts
import { useState, useEffect, useCallback } from 'react';

function useForm(initialValues: Record<string, any>) {
  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState<Record<string, any>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isTouched, setIsTouched] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitCount, setSubmitCount] = useState(0);

  useEffect(() => {
    if (JSON.stringify(values) !== JSON.stringify(initialValues)) {
      setIsDirty(true);
    } else {
      setIsDirty(false);
    }
  }, [values]);

  const handleChange = useCallback((name: string, value: any) => {
    setValues(prev => ({ ...prev, [name]: value }));
    setIsTouched(true);
  }, []);

  const reset = useCallback(() => {
    setValues(initialValues);
    setErrors({});
    setIsDirty(false);
    setIsTouched(false);
  }, []);

  const handleSubmit = useCallback((onSubmit: (values: Record<string, any>) => Promise<void>) => {
    return async (e: React.FormEvent) => {
      e.preventDefault();
      setIsSubmitting(true);
      setSubmitCount(prev => prev + 1);
      await onSubmit(values);
      setIsSubmitting(false);
    };
  }, [values]);

  return { values, errors, isDirty, isTouched, isSubmitting, submitCount, handleChange, reset, handleSubmit };
}

export default useForm;
```

